// Finds the hub device and its entities by their ORIGINAL ESPHome names, not by entity_id, so the cards work whatever
// the device name, area prefix or entity-id format in HA. ESPHome has no language-independent entity id (the HA
// unique_id contains the name), so NAMES lists every language of the packages (generated by tools/gen_names.py) and
// an entity matches by its name after the bus prefix ("<prefix> - <name>"), whatever prefix the user set.
// Without a hub the cards fall back to the Immergas Dominus integration (local TCP to the Dominus Wi-Fi module): its
// entities are matched by their key (the unique_id after the config entry id), so a reduced dashboard works with it too.
import { NAMES, Key } from "./names";

export interface HubIndex {
  deviceId: string;
  lang: "pl" | "en";
  ids: Partial<Record<Key, string>>;
  /** "hub" = the ESPHome hub, "dominus" = the Immergas Dominus integration (fewer entities, no heat-pump data) */
  source: "hub" | "dominus";
}

// Immergas Dominus entity key -> card key; the schedule entities are generated below
const DOMINUS: Record<string, Key> = {
  room_temperature: "zone1", heating_target: "zone1_set", heating_curve_offset: "u03", outdoor_temperature: "outdoor",
  dhw_tank_temperature: "tank", operation_mode: "mode", fault_code: "err_code", fault_description: "err_desc",
  fault_active: "err_active", dhw_target: "dhw_set", dhw_comfort: "dhw_comfort_dd", dhw_eco: "dhw_eco_dd",
  dhw_comfort_eco: "dhw_sched", dhw_phase: "dhw_phase", program_phase: "zone1_phase", comfort_heat: "comfort_heat",
  eco_heat: "eco_heat", comfort_cool: "comfort_cool", eco_cool: "eco_cool", heating_demand: "dom_ch_demand",
  dhw_request: "dom_dhw_request", last_successful_read: "dom_last_read", failed_polls: "dom_failed",
  humidity_target: "dom_hum_target", flow_target: "dom_flow_target", fault_language: "err_lang",
};
["mon", "tue", "wed", "thu", "fri", "sat", "sun"].forEach((d, i) => {
  DOMINUS[`weekday_${i + 1}_profile`] = `co_${d}` as Key;
  DOMINUS[`dhw_weekday_${i + 1}_profile`] = `cwu_${d}` as Key;
});
for (let p = 1; p <= 4; p++) for (let f = 1; f <= 4; f++) {
  DOMINUS[`profile${p}_fascia${f}_start`] = `k${p}z${f}on` as Key;
  DOMINUS[`profile${p}_fascia${f}_end`] = `k${p}z${f}off` as Key;
}

let cache: { index: HubIndex | null; count: number; at: number } | null = null;
let pending: Promise<void> | null = null;
let registry: Record<string, string> | null = null; // entity_id -> original_name (admin users only)
let dominusKeys: Record<string, string> = {}; // entity_id -> Immergas Dominus entity key (admin users only)

async function loadRegistry(hass: any): Promise<void> {
  try {
    const list: any[] = await hass.callWS({ type: "config/entity_registry/list" });
    const r: Record<string, string> = {};
    const d: Record<string, string> = {};
    for (const e of list) {
      if (e.platform === "esphome" && e.original_name) r[e.entity_id] = e.original_name;
      // unique_id = "<config entry id>_<key>"
      if (e.platform === "immergas_dominus" && String(e.unique_id).startsWith(e.config_entry_id + "_"))
        d[e.entity_id] = String(e.unique_id).slice(e.config_entry_id.length + 1);
    }
    registry = r;
    dominusKeys = d;
  } catch {
    registry = {}; // non-admin: fall back to friendly names
  }
}

function nameOf(hass: any, entityId: string, deviceName: string): string {
  const orig = registry?.[entityId];
  if (orig) return orig;
  const fn: string = hass.states[entityId]?.attributes?.friendly_name ?? "";
  return deviceName && fn.startsWith(deviceName + " ") ? fn.slice(deviceName.length + 1) : fn;
}

/** "Immergas DD - X" -> ["Immergas DD - X", "X"] (every tail after " - "), so any prefix matches */
function tails(n: string): string[] {
  const out = [n];
  for (let i = n.indexOf(" - "); i >= 0; i = n.indexOf(" - ", i + 1)) out.push(n.slice(i + 3));
  return out;
}

function build(hass: any): HubIndex | null {
  const ents: Record<string, any> = hass.entities ?? {};
  const [, anchor] = NAMES.state;
  let deviceId = "";
  let lang: "pl" | "en" = "pl";
  for (const [id, e] of Object.entries(ents)) {
    if (e.platform !== "esphome" || !e.device_id) continue;
    const dev = hass.devices?.[e.device_id];
    const t = tails(nameOf(hass, id, dev?.name_by_user || dev?.name || ""));
    const i = anchor.findIndex((a: string) => t.includes(a));
    if (i >= 0) {
      deviceId = e.device_id;
      lang = i === 0 ? "pl" : "en";
      break;
    }
  }
  if (!deviceId) return buildDominus(hass);
  const dev = hass.devices?.[deviceId];
  const dn = dev?.name_by_user || dev?.name || "";
  // tail -> [entity_id, full name] of every entity of the hub device
  const byTail: Record<string, [string, string][]> = {};
  for (const [id, e] of Object.entries(ents)) {
    if (e.device_id !== deviceId) continue;
    const n = nameOf(hass, id, dn);
    for (const t of tails(n)) (byTail[t] ??= []).push([id, n]);
  }
  const ids: Partial<Record<Key, string>> = {};
  for (const k of Object.keys(NAMES) as (keyof typeof NAMES)[]) {
    const [bus, names] = NAMES[k];
    for (const nm of names) {
      const c = byTail[nm];
      if (!c) continue;
      // same name on two buses (e.g. a duplicate): prefer the bus tag in the prefix ("Immergas DD - ...")
      ids[k] = (c.find(([, n]) => n.slice(0, n.length - nm.length).includes(bus)) ?? c[0])[0];
      break;
    }
  }
  return { deviceId, lang, ids, source: "hub" };
}

/** index of the Immergas Dominus integration: by entity key (admin), else by translation key where it is unique */
function buildDominus(hass: any): HubIndex | null {
  const ents: Record<string, any> = hass.entities ?? {};
  const ids: Partial<Record<Key, string>> = {};
  let deviceId = "";
  for (const [id, e] of Object.entries(ents)) {
    if (e.platform !== "immergas_dominus") continue;
    const k = DOMINUS[dominusKeys[id] ?? e.translation_key ?? ""];
    if (k && !ids[k]) ids[k] = id;
    if (e.translation_key === "fault_code") deviceId = e.device_id ?? "";
  }
  if (!deviceId) return null;
  const l = String(hass?.locale?.language ?? hass?.language ?? "en").slice(0, 2);
  return { deviceId, lang: l === "pl" ? "pl" : "en", ids, source: "dominus" };
}

let dominusCache: { index: HubIndex | null; count: number; at: number } | null = null;

/** Returns the hub index (null until found). Rebuilds when the entity count changes. `source: "dominus"` (card option,
 *  set by the Dominus strategy) uses the Dominus integration even when a hub is present too. */
export function hubIndex(hass: any, onReady: () => void, source?: string): HubIndex | null {
  if (registry === null) {
    if (!pending) pending = loadRegistry(hass).then(() => { cache = null; onReady(); });
    return null;
  }
  const count = Object.keys(hass.entities ?? {}).length;
  if (source === "dominus") {
    if (!dominusCache || dominusCache.count !== count || (!dominusCache.index && Date.now() - dominusCache.at > 10000))
      dominusCache = { index: buildDominus(hass), count, at: Date.now() };
    return dominusCache.index;
  }
  if (!cache || cache.count !== count || (!cache.index && Date.now() - cache.at > 10000)) {
    cache = { index: build(hass), count, at: Date.now() };
  }
  return cache.index;
}
